package com.safaan.worldforge;

import android.app.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
import com.safaan.worldforge.engine.blocks.*;import com.safaan.worldforge.engine.rendering.WorldRenderer;import com.safaan.worldforge.engine.world.World;

public final class MainActivity extends Activity{
 private WorldRenderer renderer;private Block selected=Block.GRASS;private final Block[] inventory=Blocks.HOTBAR.clone();private TextView status;private boolean running;
 private File saveFile(){return new File(getFilesDir(),"worldforge.wld");}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(1024,1024);immersive();showMenu();}
 private void immersive(){getWindow().getDecorView().setSystemUiVisibility(5894|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_LAYOUT_STABLE);}
 private TextView label(String s,float z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.WHITE);t.setGravity(Gravity.CENTER);return t;}
 private TextView control(String s){TextView t=label(s,15);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setTextColor(Color.WHITE);t.setBackground(round(Color.argb(190,35,42,50),18));t.setPadding(8,4,8,4);t.setClickable(true);return t;}
 private GradientDrawable round(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(r);d.setStroke(2,Color.argb(80,255,255,255));return d;}
 private void showMenu(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);box.setPadding(70,30,70,30);box.setBackgroundColor(Color.rgb(25,32,38));TextView title=label("WORLD FORGE",38);box.addView(title,new LinearLayout.LayoutParams(-1,120));TextView play=control("PLAY"),create=control("CREATE WORLD"),settings=control("SETTINGS");addMenu(box,play);addMenu(box,create);addMenu(box,settings);play.setOnClickListener(v->startWorld(false));create.setOnClickListener(v->startWorld(true));settings.setOnClickListener(v->showSettings());setContentView(box);}
 private void addMenu(LinearLayout p,View v){LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(-1,78);q.setMargins(0,8,0,8);p.addView(v,q);}
 private void startWorld(boolean fresh){long seed;World.SaveData data=null;if(fresh||!saveFile().exists())seed=new Random().nextLong();else{try{data=World.load(saveFile());seed=data.seed;}catch(Exception e){seed=1234567L;}}renderer=new WorldRenderer(new World(seed));if(data!=null){renderer.x=data.x;renderer.y=data.y;renderer.z=data.z;renderer.yaw=data.yaw;renderer.pitch=data.pitch;renderer.world.apply(data);if(data.inventory!=null)System.arraycopy(data.inventory,0,inventory,0,Math.min(inventory.length,data.inventory.length));if(data.selected>=0&&data.selected<inventory.length)selected=inventory[data.selected];}running=true;buildGame();}
 private void buildGame(){FrameLayout root=new FrameLayout(this);GameView view=new GameView();root.addView(view,new FrameLayout.LayoutParams(-1,-1));TextView cross=label("+",30);root.addView(cross,new FrameLayout.LayoutParams(70,70,Gravity.CENTER));
  status=label("",18);status.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);status.setShadowLayer(4,2,2,Color.BLACK);FrameLayout.LayoutParams sp=new FrameLayout.LayoutParams(-2,62,Gravity.TOP|Gravity.LEFT);sp.setMargins(20,10,0,0);root.addView(status,sp);
  TextView jump=control("JUMP"),br=control("BREAK"),pl=control("PLACE"),inv=control("INV");add(root,jump,Gravity.RIGHT|Gravity.BOTTOM,20,122,138,78);add(root,br,Gravity.RIGHT|Gravity.BOTTOM,170,122,138,78);add(root,pl,Gravity.RIGHT|Gravity.BOTTOM,320,122,138,78);add(root,inv,Gravity.RIGHT|Gravity.TOP,20,20,100,65);
  jump.setOnClickListener(v->renderer.jump());br.setOnClickListener(v->renderer.breakBlock());pl.setOnClickListener(v->renderer.placeBlock(selected));inv.setOnClickListener(v->showInventory());
  LinearLayout hot=new LinearLayout(this);hot.setOrientation(LinearLayout.HORIZONTAL);hot.setPadding(4,4,4,4);hot.setBackground(round(Color.argb(155,15,18,22),12));
  for(int i=0;i<inventory.length;i++){final int n=i;TextView s=control((i+1)+"\n"+shortName(inventory[i]));s.setTextSize(11);s.setOnClickListener(v->{selected=inventory[n];updateStatus();});LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(0,82,1);q.setMargins(3,0,3,0);hot.addView(s,q);}
  FrameLayout.LayoutParams hp=new FrameLayout.LayoutParams(-1,90,Gravity.BOTTOM);hp.setMargins(14,0,14,14);root.addView(hot,hp);setContentView(root);immersive();updateStatus();}
 private String shortName(Block b){String n=b.name().toLowerCase(Locale.US);return n.length()>7?n.substring(0,7):n;}
 private void showInventory(){String[] names=new String[inventory.length];for(int i=0;i<names.length;i++)names[i]=(i+1)+"  "+inventory[i].name();new AlertDialog.Builder(this).setTitle("Inventory").setItems(names,(d,w)->{selected=inventory[w];updateStatus();}).setNegativeButton("CLOSE",null).show();}
 private void showSettings(){new AlertDialog.Builder(this).setTitle("World Forge Settings").setMessage("Landscape sensor rotation\n12-chunk render distance\nTouch camera + joystick\nAutomatic world saving\n60 FPS target").setPositiveButton("OK",null).show();}
 private void updateStatus(){if(status!=null)status.setText("♥ 100    "+selected.name());}
 private void add(FrameLayout r,View v,int gravity,int margin,int bottom,int w,int h){FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(w,h,gravity);p.setMargins(margin,0,0,bottom);r.addView(v,p);}
 @Override protected void onPause(){super.onPause();if(running&&renderer!=null)save();}
 private void save(){try{int sel=0;for(int i=0;i<inventory.length;i++)if(inventory[i]==selected)sel=i;renderer.world.save(saveFile(),renderer.x,renderer.y,renderer.z,renderer.yaw,renderer.pitch,inventory,sel);}catch(Exception ignored){}}
 private final class GameView extends android.opengl.GLSurfaceView{float lx,ly;boolean moving;GameView(){super(MainActivity.this);setEGLContextClientVersion(2);setRenderer(renderer);setRenderMode(RENDERMODE_CONTINUOUSLY);setFocusable(true);}
  @Override public boolean onTouchEvent(MotionEvent e){float tx=e.getX(),ty=e.getY();int a=e.getActionMasked();if(a==MotionEvent.ACTION_DOWN){lx=tx;ly=ty;moving=tx<getWidth()*.42f;return true;}if(a==MotionEvent.ACTION_MOVE){float dx=tx-lx,dy=ty-ly;if(moving){float sx=Math.max(-1,Math.min(1,(tx-getWidth()*.20f)/(getWidth()*.20f)));float f=Math.max(-1,Math.min(1,(getHeight()*.70f-ty)/(getHeight()*.35f)));renderer.setInput(f,sx);}else renderer.turn(dx,dy);lx=tx;ly=ty;return true;}if(a==MotionEvent.ACTION_UP||a==MotionEvent.ACTION_CANCEL){if(moving)renderer.setInput(0,0);return true;}return true;}
 }
}